import{_ as o,c as t,b as l,o as n}from"./app-DKvarYBr.js";const a={};function r(c,e){return n(),t("div",null,e[0]||(e[0]=[l('<p>By this time, you might have started using the  <a href="https://store.webkul.com/Shopify-Multi-Vendor-Marketplace.html" target="_blank" rel="noopener noreferrer">Multivendor Marketplace App for Shopify</a> and you would want to have your Collections from the Shopify Store to be synced to the App.</p><p>This manual will help you understand how you can create Collections in the App.</p><p>Please make sure that you have a fair idea about the type of Collections in Shopify, ie. <a href="https://help.shopify.com/en/manual/products/collections" target="_blank" rel="noopener noreferrer">Manual and Automatic/Smart Collections</a>. You can also check the same from here.</p><h3 id="admin-end" tabindex="-1"><a class="header-anchor" href="#admin-end"><span>Admin End</span></a></h3><p>First, understand the Admin end from the App:</p><p>You need to restrict the collection from the &quot;Restriction Configuration&quot; so that you can manage the collections here from the App.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/col1.webp" target="_blank" rel="noopener noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/col1.webp" alt="Configuration"></a></p><p>Now once this is done, you will now have the &quot;Collection&quot; menu under the Products menu in the App:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/col2.webp" target="_blank" rel="noopener noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/col2.webp" alt="Collection"></a></p><p>You can use the &quot;Sync&quot; button to sync all the Collections from the Shopify Store to the Multivendor App.</p><p>Once synced, Admin can even enable/disable the Collection from the App. If the collection is enabled from the App then</p><p><strong>NOTE:</strong> Please note that the list on the collection page will only show the &quot;manual collections&quot; listed. Although the smart collections are also synced to the App.</p><p>Also, make a note that the <a href="https://webkul.com/blog/shopify-multivendor-marketplace-commissions-new-theme" target="_blank" rel="noopener noreferrer">Collection Commission</a> is only applied to manual collections only.</p><p>The Admin can view the Smart Collections from here on the Add/Edit Product Page:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/col3.webp" target="_blank" rel="noopener noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/col3.webp" alt="View smart Collection"></a></p><p>Admin can restrict whether the collections can be shown to the seller or not, from the &quot;restriction configuration&quot; menu:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/col4.webp" target="_blank" rel="noopener noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/col4.webp" alt="Restrict Collection"></a></p><h3 id="seller-end" tabindex="-1"><a class="header-anchor" href="#seller-end"><span>Seller End</span></a></h3><p>The Collections are now synced to the app, now check how things will appear at the seller end:</p><p>The seller can view the manual collection on the &quot;Add product&quot; page:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/col5.webp" target="_blank" rel="noopener noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/col5.webp" alt="Products"></a></p><p>The seller can view the smart collection either as shown in the above screenshot on the add product page or can view the smart collection from the menu &quot;smart collection&quot;:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/col6.webp" target="_blank" rel="noopener noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/col6.webp" alt="Collection"></a></p><h3 id="shopify-multivendor-marketplace-demo" tabindex="-1"><a class="header-anchor" href="#shopify-multivendor-marketplace-demo"><span>Shopify Multivendor Marketplace Demo</span></a></h3><p>Check out: <a href="https://multivendor-marketplace-5.myshopify.com/" target="_blank" rel="noopener noreferrer">https://multivendor-marketplace-5.myshopify.com/</a></p>',25)]))}const i=o(a,[["render",r]]),s=JSON.parse('{"path":"/zenith/products/Collection-sync.html","title":"Collection sync","lang":"en-US","frontmatter":{"title":"Collection sync","description":"Collection sync","date":"2025-07-02T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":3,"title":"Admin End","slug":"admin-end","link":"#admin-end","children":[]},{"level":3,"title":"Seller End","slug":"seller-end","link":"#seller-end","children":[]},{"level":3,"title":"Shopify Multivendor Marketplace Demo","slug":"shopify-multivendor-marketplace-demo","link":"#shopify-multivendor-marketplace-demo","children":[]}],"git":{"updatedTime":1759748118000,"contributors":[{"name":"pratik","username":"pratik","email":"pratik@webkul.com","commits":3,"url":"https://github.com/pratik"}],"changelog":[{"hash":"90ec5b5f52eba83d1e9c295c7ccf89e3db66275b","time":1759748118000,"email":"pratik@webkul.com","author":"pratik","message":"fix conflcit"},{"hash":"52c8b1d26d49bc54550dc3b20ce6d442bb390c03","time":1753692029000,"email":"pratik@webkul.com","author":"pratik","message":"fix conflcit"},{"hash":"769a52a9d6ea585a51f97bd9091014ed466fba2c","time":1751543091000,"email":"pratik@webkul.com","author":"pratik","message":"fix conflcit"}]},"filePathRelative":"zenith/products/Collection-sync.md"}');export{i as comp,s as data};
